<script setup lang="ts">import { ref } from 'vue';import { useRouter } from 'vue-router';import { useAuthStore } from '../stores/auth';const demoMode=import.meta.env.DEV;const auth=useAuthStore();const router=useRouter();const identifier=ref(demoMode?'customer@machiservice.jp':'');const password=ref(demoMode?'Demo1234!':'');const error=ref('');const loading=ref(false);async function submit():Promise<void>{loading.value=true;error.value='';try{await auth.login(identifier.value,password.value);await router.push('/');}catch{error.value='メールアドレスまたはパスワードを確認してください。';}finally{loading.value=false;}}</script>
<template><section class="auth-page"><form class="auth-card" @submit.prevent="submit"><div class="brand"><span class="brand-mark">ま</span><span>まちサービス</span></div><span class="eyebrow">WELCOME BACK</span><h1>おかえりなさい</h1><p>ログインして、お気に入りや問い合わせを確認できます。</p><label>メールアドレス / 電話番号<input v-model="identifier" autocomplete="username"></label><label>パスワード<input v-model="password" type="password" autocomplete="current-password"></label><span v-if="error" class="error">{{ error }}</span><button class="primary" :disabled="loading">{{ loading?'ログイン中…':'ログイン' }}</button><small v-if="demoMode">デモアカウントを入力済みです</small><hr><p>アカウントをお持ちでない方 <a>無料登録</a></p></form><div class="auth-image"><blockquote>“地域の暮らしと、<br>頼れるプロをつなぐ。”</blockquote></div></section></template>
